"""MCP server configuration loaded from ``integrations.yml``.

Mantle declares MCP tool servers under ``mcp_servers:`` as a list of records
with a required ``name``. Auth uses the same top-level keys as CALM
(``token``, ``api_key``, ``oauth``, ``module``); they fold into
``additional_params`` for
:class:`~rasa.shared.utils.mcp.server_connection.MCPServerConnection`.
"""

from __future__ import annotations

from pathlib import Path
from typing import Any, Mapping, Optional, Sequence, Union

import structlog
from pydantic import BaseModel, ConfigDict, Field, ValidationError

from rasa.exceptions import ValidationError as RasaValidationError
from rasa.mantle.config.integrations import MCPServerSpec
from rasa.shared.exceptions import RasaException
from rasa.shared.project_structure import MANTLE_INTEGRATIONS_FILE
from rasa.shared.utils.yaml import read_yaml_file

structlogger = structlog.get_logger()

MCP_SERVERS_KEY = "mcp_servers"


class MCPServersSettings(BaseModel):
    """Parsed ``mcp_servers:`` block from ``integrations.yml``."""

    model_config = ConfigDict(frozen=True)

    servers: dict[str, MCPServerSpec] = Field(default_factory=dict)

    def to_connection_config(self, server_id: str) -> dict[str, Any]:
        """Build a dict suitable for ``MCPServerConnection.from_config``.

        Args:
            server_id: ``name`` of the server under ``mcp_servers:``.

        Returns:
            Mapping with ``name``, ``url``, ``type``, and ``additional_params``.

        Raises:
            KeyError: If ``server_id`` is not configured.
        """
        try:
            server = self.servers[server_id]
        except KeyError as error:
            raise KeyError(
                f"Unknown MCP server id '{server_id}'. Configured servers: "
                f"{sorted(self.servers)!r}."
            ) from error
        return {
            "name": server.name,
            "url": server.url,
            "type": server.type,
            "additional_params": dict(server.additional_params),
        }


def parse_mcp_servers(raw_mcp_servers: Sequence[Any]) -> MCPServersSettings:
    """Validate a raw ``mcp_servers:`` list from ``integrations.yml``.

    Args:
        raw_mcp_servers: List of server mappings, each with a ``name``.

    Returns:
        Validated :class:`MCPServersSettings` indexed by server name.

    Raises:
        RasaException: If an entry is not a mapping, names collide, or an
            entry fails schema validation.
    """
    servers: dict[str, MCPServerSpec] = {}
    for index, raw_config in enumerate(raw_mcp_servers):
        if not isinstance(raw_config, Mapping):
            raise RasaException(
                f"MCP server at index {index} in '{MANTLE_INTEGRATIONS_FILE}' must "
                f"be a mapping, but got '{type(raw_config).__name__}'."
            )
        try:
            server = MCPServerSpec.model_validate(dict(raw_config))
        except (ValidationError, RasaValidationError) as error:
            raise RasaException(
                f"Invalid configuration for MCP server at index {index} in "
                f"'{MANTLE_INTEGRATIONS_FILE}': {error}"
            ) from error
        if server.name in servers:
            raise RasaException(
                f"Duplicate MCP server name '{server.name}' in "
                f"'{MANTLE_INTEGRATIONS_FILE}'; names must be unique."
            )
        servers[server.name] = server
    return MCPServersSettings(servers=servers)


def load_integration_mcp_servers(
    project_root: Union[str, Path],
) -> Optional[MCPServersSettings]:
    """Load MCP server configuration from a project's ``integrations.yml``.

    Auth secrets must stay as ``${ENV}`` placeholders for
    :func:`~rasa.shared.agents.auth.utils.validate_secrets_in_params` and for
    deferred resolution inside ``AgentAuthStrategy``. Environment variables are
    therefore *not* expanded at read time (same as train-time validation).

    Args:
        project_root: Directory expected to contain ``integrations.yml``.

    Returns:
        Validated settings, or ``None`` if the file does not exist or does not
        declare a ``mcp_servers:`` block.

    Raises:
        RasaException: If ``mcp_servers:`` is present but not a list, or an
            entry fails validation.
    """
    integration_file = Path(project_root) / MANTLE_INTEGRATIONS_FILE
    if not integration_file.is_file():
        return None

    raw = read_yaml_file(integration_file, expand_env_vars=False)
    if not isinstance(raw, Mapping):
        return None

    raw_mcp_servers = raw.get(MCP_SERVERS_KEY)
    if raw_mcp_servers is None:
        return None
    if not isinstance(raw_mcp_servers, list):
        raise RasaException(
            f"'{MCP_SERVERS_KEY}' in '{MANTLE_INTEGRATIONS_FILE}' must be a list "
            "of server configurations."
        )

    settings = parse_mcp_servers(raw_mcp_servers)
    structlogger.debug(
        "mantle.mcp.loaded_from_integration",
        server_count=len(settings.servers),
        server_ids=sorted(settings.servers),
    )
    return settings
